patch:
diff --git a/repro-no-useless-assignment-try-catch.js b/repro-no-useless-assignment-try-catch.js
new file mode 100644
index 0000000..5bd39fe
--- /dev/null
+++ b/repro-no-useless-assignment-try-catch.js
@@ -0,0 +1,97 @@
+"use strict";
+
+/*
+ * Reproduction: no-useless-assignment false positive when a `try` block
+ * contains `return`/`break` and the assigned value is read in `catch`.
+ * Run: node repro-no-useless-assignment-try-catch.js
+ */
+
+const { Linter } = require("./lib/api");
+
+const linter = new Linter();
+const config = {
+    languageOptions: { ecmaVersion: "latest", sourceType: "module" },
+    rules: { "no-useless-assignment": "error" }
+};
+
+const cases = [
+    {
+        name: "BUG: issue example (return in try, value read in catch)",
+        expectReport: false,
+        code: `
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}
+function unsafeFn() { throw new Error(); }`
+    },
+    {
+        name: "BUG: break in try inside a loop, value read in catch",
+        expectReport: false,
+        code: `
+function fn() {
+  let v;
+  while (cond()) {
+    try {
+      v = 42;
+      unsafeFn();
+      break;
+    } catch {
+      use(v);
+    }
+  }
+}`
+    },
+    {
+        name: "control: same code without return in try (not reported)",
+        expectReport: false,
+        code: `
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+  } catch {
+    return { intermediaryValue };
+  }
+}
+function unsafeFn() { throw new Error(); }`
+    },
+    {
+        name: "control: genuinely useless assignment (reported)",
+        expectReport: true,
+        code: `
+function fn() {
+  let v;
+  v = 1;
+  v = 42;
+  return v;
+}`
+    }
+];
+
+let failed = 0;
+
+for (const { name, code, expectReport } of cases) {
+    const messages = linter.verify(code, config);
+    const reported = messages.filter(m => m.ruleId === "no-useless-assignment");
+    const ok = (reported.length > 0) === expectReport;
+
+    if (!ok) {
+        failed++;
+    }
+    console.log(`${ok ? "PASS" : "FAIL"}  ${name}`);
+    console.log(`      expected ${expectReport ? "a report" : "no report"}, got ${reported.length}`);
+    for (const m of reported) {
+        console.log(`      ${m.line}:${m.column} ${m.message}`);
+    }
+}
+
+console.log(failed ? `\n${failed} case(s) show the bug.` : "\nNo bug observed.");
+process.exitCode = failed ? 1 : 0;
